  gap: 0.5rem;
  padding: 0 0.625rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface);
  color: var(--mc-text-muted);
}

.mc-search:focus-within {
  border-color: var(--mc-accent-border);
}

.mc-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--mc-text-primary);
}

.mc-projects-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 20rem;
  gap: 0.875rem;
  align-items: start;
}

.mc-project-table-v2 {
  min-width: 0;
  overflow: hidden;
}

.mc-project-table-head,
.mc-project-row-v2 {
  display: grid;
  grid-template-columns:
    minmax(11rem, 1.35fr)
    6.25rem
    7.25rem
    6.5rem
    5rem
    minmax(11rem, 1fr);
  gap: 0.75rem;
  align-items: center;
}

.mc-project-table-head {
  min-height: 2.375rem;
  padding: 0 0.875rem;
  border-bottom: 0.0625rem solid var(--mc-border);
  background: var(--mc-surface-raised);
  color: var(--mc-text-muted);
  font-size: 0.625rem;
  font-weight: 650;
  letter-spacing: 0.045em;
  text-transform: uppercase;
}

.mc-project-row-v2 {
  width: 100%;
  min-height: 4rem;
  padding: 0.625rem 0.875rem;
  border: 0;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
  background: transparent;
  color: var(--mc-text-secondary);
  text-align: left;
  cursor: pointer;
}

.mc-project-row-v2:last-child {
  border-bottom: 0;
}

.mc-project-row-v2:hover,
.mc-project-row-v2.is-selected {
  background: var(--mc-surface-hover);
}

.mc-project-row-v2.is-selected {
  box-shadow: inset 0.125rem 0 0 var(--mc-accent);
}

.mc-project-identity {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.mc-project-identity strong {
  overflow: hidden;
  color: var(--mc-text-primary);
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mc-project-identity small {
  overflow: hidden;
  margin-top: 0.25rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mc-current-step-cell {
  overflow: hidden;
  color: var(--mc-text-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mc-project-version {
  color: var(--mc-text-muted);
  font-size: 0.75rem;
}

.mc-project-preview {
  position: sticky;
  top: 1rem;
  padding: 1rem;
}

.mc-project-preview-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.mc-project-preview-heading h2 {
  margin: 0;
  font-size: 1rem;
}

.mc-project-preview-description {
  margin: 0.875rem 0 1rem;
  color: var(--mc-text-secondary);
  font-size: 0.8125rem;
  line-height: 1.55;
}

.mc-preview-current-step {
  padding: 0.875rem;
  margin-bottom: 1rem;
  border: 0.0625rem solid var(--mc-border-subtle);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
}

.mc-preview-current-step > span {
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-preview-current-step strong {
  display: block;
  margin: 0.375rem 0 0.625rem;
  font-size: 0.875rem;
  line-height: 1.4;
}

.mc-badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
}

.mc-inspector-list {
  margin: 0 0 1rem;
}

.mc-inspector-list > div {
  display: flex;
  min-height: 2.25rem;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
}

.mc-inspector-list > div:last-child {
  border-bottom: 0;
}

.mc-inspector-list dt {
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-inspector-list dd {
  margin: 0;
  color: var(--mc-text-secondary);
  font-size: 0.75rem;
  text-align: right;
}

.mc-project-empty {
  display: flex;
  min-height: 22rem;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 3rem;
  text-align: center;
}

.mc-empty-icon {
  display: grid;
  width: 3.5rem;
  height: 3.5rem;
  place-items: center;
  margin-bottom: 1rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-lg);
  background: var(--mc-surface-raised);
  color: var(--mc-text-muted);
}

.mc-project-empty h2 {
  margin: 0;
  font-size: 0.9375rem;
}

.mc-project-empty p {
  max-width: 28rem;
  margin: 0.5rem 0 0;
  color: var(--mc-text-secondary);
  line-height: 1.55;
}

.mc-empty-action {
  margin-top: 1rem;
}

/* Project detail */

.mc-project-detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
  margin-bottom: 1.25rem;
}

.mc-title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.mc-project-title-block > p {
  max-width: 44rem;
  margin: 0.5rem 0 0;
  color: var(--mc-text-secondary);
  line-height: 1.5;
}

.mc-project-meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4375rem;
  margin-top: 0.75rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-meta-separator {
  color: var(--mc-text-faint);
}

.mc-more-button {
  color: var(--mc-danger);
}

.mc-detail-tabs {
  display: flex;
  gap: 0.125rem;
  overflow-x: auto;
  margin: 0 -0.25rem 1rem;
  padding: 0 0.25rem 0.625rem;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
}

.mc-detail-tabs button {
  flex: 0 0 auto;
  padding: 0.4375rem 0.625rem;
  border: 0;
  border-radius: var(--mc-radius-sm);
  background: transparent;
  color: var(--mc-text-muted);
  font-size: 0.75rem;
  cursor: pointer;
}

.mc-detail-tabs button.is-active {
  background: var(--mc-surface-raised);
  color: var(--mc-text-primary);
}

.mc-detail-tabs button:disabled {
  opacity: 0.42;
  cursor: default;
}

.mc-project-detail-grid-v2 {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 19rem;
  gap: 0.875rem;
  align-items: start;
}

.mc-project-detail-main-v2 {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.875rem;
}

.mc-current-step-card {
  padding: 1.25rem;
  border-color: var(--mc-accent-border);
  background:
    linear-gradient(180deg, var(--mc-accent-soft), transparent 70%),
    var(--mc-surface);
}

.mc-section-topline {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.mc-current-step-card h2 {
  max-width: 48rem;
  margin: 0;
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  line-height: 1.3;
}

.mc-step-context {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4375rem;
  margin-top: 1rem;
  color: var(--mc-text-muted);
  font-size: 0.75rem;
}

.mc-detail-pair {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.875rem;
}

.mc-detail-section-v2 {
  min-height: 14rem;
  padding: 1rem;
}

.mc-section-heading-inline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.75rem;
}

.mc-section-heading-inline h2 {
  margin: 0;
  font-size: 0.875rem;
}

.mc-section-heading-inline > span {
  display: grid;
  min-width: 1.5rem;
  height: 1.5rem;
  place-items: center;
  border-radius: 999px;
  background: var(--mc-surface-raised);
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-work-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 0;
  margin: 0;
  list-style: none;
}

.mc-work-list li {
  display: flex;
  min-height: 2.5rem;
  align-items: flex-start;
  gap: 0.625rem;
  padding: 0.625rem 0;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
  color: var(--mc-text-secondary);
  line-height: 1.45;
}

.mc-work-list li:last-child {
  border-bottom: 0;
}

.mc-work-index {
  display: grid;
  width: 1.25rem;
  height: 1.25rem;
  flex: 0 0 auto;
  place-items: center;
  border: 0.0625rem solid var(--mc-border);
  border-radius: 50%;
  color: var(--mc-text-muted);
  font-size: 0.625rem;
}

.mc-blocker-dot {
  width: 0.4375rem;
  height: 0.4375rem;
  flex: 0 0 auto;
  margin-top: 0.4rem;
  border-radius: 50%;
  background: var(--mc-danger);
}

.mc-clear-state {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--mc-success);
  font-size: 0.8125rem;
}

.mc-last-completed-card {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem;
}

.mc-last-completed-icon {
  display: grid;
  width: 2rem;
  height: 2rem;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 50%;
  background: var(--mc-success-soft);
  color: var(--mc-success);
}

.mc-last-completed-card strong {
  font-size: 0.8125rem;
}

.mc-project-inspector-v2 {
  position: sticky;
  top: 1rem;
  padding: 1rem;
}

.mc-inspector-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.625rem;
}

.mc-inspector-heading h2 {
  margin: 0;
  font-size: 0.9375rem;
}

.mc-inspector-heading svg {
  color: var(--mc-text-muted);
}

.mc-inspector-divider {
  height: 0.0625rem;
  margin: 0.875rem 0;
  background: var(--mc-border-subtle);
}

.mc-location-block + .mc-location-block {
  margin-top: 1rem;
}

.mc-location-label {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  margin-bottom: 0.375rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-location-block code,
.mc-location-block a {
  display: block;
  overflow: hidden;
  color: var(--mc-text-secondary);
  font-family: inherit;
  font-size: 0.6875rem;
  line-height: 1.45;
  text-overflow: ellipsis;
  text-decoration: none;
  word-break: break-all;
}

.mc-location-block a:hover {
  color: var(--mc-accent);
}

/* Forms */

.mc-project-form-v2 {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
}

.mc-form-section {
  display: grid;
  grid-template-columns: 14rem minmax(0, 1fr);
  gap: 2rem;
  padding: 1.25rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface);
}

.mc-form-section-copy h2 {
  margin: 0;
  font-size: 0.9375rem;
}

.mc-form-section-copy > p:last-child {
  margin: 0.5rem 0 0;
  color: var(--mc-text-muted);
  font-size: 0.75rem;
  line-height: 1.5;
}

.mc-form-section-fields {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1rem;
}

.mc-form-split {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.875rem;
}

.mc-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.375rem;
}

.mc-field > span,
.mc-option-picker legend {
  color: var(--mc-text-secondary);
  font-size: 0.6875rem;
  font-weight: 600;
}

.mc-field input,
.mc-field textarea {
  width: 100%;
  padding: 0.625rem 0.6875rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  outline: 0;
  background: var(--mc-surface-raised);
  color: var(--mc-text-primary);
}

.mc-field input {
  min-height: 2.375rem;
}

.mc-field textarea {
  resize: vertical;
  line-height: 1.5;
}

.mc-field input:focus,
.mc-field textarea:focus {
  border-color: var(--mc-accent-border);
  box-shadow: 0 0 0 0.125rem var(--mc-accent-soft);
}

.mc-field input::placeholder,
.mc-field textarea::placeholder {
  color: var(--mc-text-faint);
}

.mc-option-picker {
  min-width: 0;
  padding: 0;
  margin: 0;
  border: 0;
}

.mc-option-picker legend {
  padding: 0;
  margin-bottom: 0.4375rem;
}

.mc-option-picker-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
}

.mc-option-choice {
  --badge-color: var(--mc-text-secondary);
  --badge-bg: var(--mc-neutral-soft);
  display: inline-flex;
  min-height: 2rem;
  align-items: center;
  gap: 0.375rem;
  padding: 0 0.625rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  color: var(--mc-text-secondary);
  cursor: pointer;
}

.mc-option-choice:hover {
  border-color: var(--mc-border-strong);
}

.mc-option-choice.is-selected {
  border-color: color-mix(in srgb, var(--badge-color) 42%, var(--mc-border));
  background: var(--badge-bg);
  color: var(--badge-color);
}

.mc-option-dot {
  width: 0.375rem;
  height: 0.375rem;
  border-radius: 50%;
  background: currentColor;
}

.mc-form-error {
  padding: 0.75rem 0.875rem;
  margin: 0;
  border: 0.0625rem solid color-mix(in srgb, var(--mc-danger) 35%, transparent);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-danger-soft);
  color: var(--mc-danger);
}

.mc-form-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding-top: 0.25rem;
}

/* Dialogs */

.mc-dialog-backdrop {
  position: fixed;
  z-index: 100;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background: var(--mc-overlay);
}

.mc-dialog {
  position: relative;
  width: min(30rem, 100%);
  max-height: calc(100vh - 3rem);
  overflow: hidden;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-lg);
  background: var(--mc-surface-elevated);
  box-shadow: var(--mc-shadow);
}

.mc-dialog-wide {
  width: min(68rem, 100%);
}

.mc-dialog-header {
  padding: 1rem 1.125rem;
  border-bottom: 0.0625rem solid var(--mc-border);
}

.mc-dialog-header h2,
.mc-confirm-copy h2 {
  margin: 0;
  font-size: 1rem;
}

.mc-dialog-scroll {
  max-height: calc(100vh - 9rem);
  overflow: auto;
  padding: 1rem;
}

.mc-confirm-dialog {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.875rem;
  padding: 1.125rem;
}

.mc-confirm-icon {
  display: grid;
  width: 2.25rem;
  height: 2.25rem;
  place-items: center;
  border-radius: 50%;
  background: var(--mc-warning-soft);
  color: var(--mc-warning);
}

.mc-confirm-icon.is-danger {
  background: var(--mc-danger-soft);
  color: var(--mc-danger);
}

.mc-confirm-copy p {
  margin: 0.4375rem 0 0;
  color: var(--mc-text-secondary);
  font-size: 0.8125rem;
  line-height: 1.5;
}

.mc-dialog-close {
  border: 0;
  background: transparent;
}

.mc-dialog-actions {
  display: flex;
  grid-column: 2 / -1;
  justify-content: flex-end;
  gap: 0.5rem;
  margin-top: 0.375rem;
}

/* Settings */

.mc-settings-layout {
  display: grid;
  grid-template-columns: 14rem minmax(0, 1fr);
  gap: 1.5rem;
  align-items: start;
}

.mc-settings-nav {
  display: flex;
  flex-direction: column;
  gap: 0.1875rem;
}

.mc-settings-nav-item {
  display: flex;
  min-height: 2.25rem;
  align-items: center;
  gap: 0.625rem;
  padding: 0 0.625rem;
  border-radius: var(--mc-radius-sm);
  color: var(--mc-text-secondary);
  text-decoration: none;
}

.mc-settings-nav-item:hover {
  background: var(--mc-surface-hover);
  color: var(--mc-text-primary);
}

.mc-settings-nav-item.is-active {
  background: var(--mc-accent-soft);
  color: var(--mc-text-primary);
}

.mc-settings-content {
  min-width: 0;
  max-width: 58rem;
}

.mc-settings-heading {
  margin-bottom: 1rem;
}

.mc-settings-heading h2 {
  margin: 0;
  font-size: 1rem;
}

.mc-settings-heading p {
  margin: 0.375rem 0 0;
  color: var(--mc-text-muted);
  font-size: 0.75rem;
}

.mc-settings-group {
  overflow: hidden;
}

.mc-setting-row,
.mc-scale-header {
  display: flex;
  min-height: 4rem;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  padding: 0.875rem 1rem;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
}

.mc-setting-row:last-child {
  border-bottom: 0;
}

.mc-setting-row > div,
.mc-scale-header > div {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.mc-setting-row strong,
.mc-scale-header strong {
  font-size: 0.8125rem;
}

.mc-setting-row span,
.mc-scale-header span {
  color: var(--mc-text-muted);
  font-size: 0.75rem;
  line-height: 1.45;
}

.mc-toggle {
  position: relative;
  width: 2.375rem;
  height: 1.375rem;
  flex: 0 0 auto;
  padding: 0;
  border: 0.0625rem solid var(--mc-border);
  border-radius: 999px;
  background: var(--mc-surface-raised);
  cursor: pointer;
}

.mc-toggle span {
  position: absolute;
  top: 0.1875rem;
  left: 0.1875rem;
  width: 0.875rem;
  height: 0.875rem;
  border-radius: 50%;
  background: var(--mc-text-muted);
  transition: transform 140ms ease;
}

.mc-toggle.is-on {
  border-color: var(--mc-accent);
  background: var(--mc-accent);
}

.mc-toggle.is-on span {
  background: #fff;
  transform: translateX(1rem);
}

.mc-theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.625rem;
}

.mc-theme-choice {
  display: flex;
  min-height: 6rem;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.875rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface);
  text-align: left;
  cursor: pointer;
}

.mc-theme-choice:hover {
  background: var(--mc-surface-hover);
}

.mc-theme-choice.is-selected {
  border-color: var(--mc-accent);
  box-shadow: inset 0 0 0 0.0625rem var(--mc-accent);
}

.mc-theme-choice svg {
  margin-top: 0.0625rem;
  color: var(--mc-text-secondary);
}

.mc-theme-choice.is-selected svg {
  color: var(--mc-accent);
}

.mc-theme-choice > span {
  display: flex;
  flex-direction: column;
}

.mc-theme-choice strong {
  font-size: 0.8125rem;
}

.mc-theme-choice small {
  margin-top: 0.3125rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
  line-height: 1.45;
}

.mc-scale-value {
  color: var(--mc-accent);
}

.mc-scale-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
  padding: 1rem;
}

.mc-scale-choice {
  min-height: 2.5rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  color: var(--mc-text-secondary);
  cursor: pointer;
}

.mc-scale-choice:hover {
  background: var(--mc-surface-hover);
}

.mc-scale-choice.is-selected {
  border-color: var(--mc-accent);
  background: var(--mc-accent-soft);
  color: var(--mc-accent);
  font-weight: 650;
}

.mc-setting-note {
  padding: 0.75rem 1rem;
  border-top: 0.0625rem solid var(--mc-border-subtle);
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
  line-height: 1.5;
}

.mc-settings-content-card,
.mc-about-card {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1rem;
}

.mc-settings-card-icon {
  display: grid;
  width: 2.25rem;
  height: 2.25rem;
  flex: 0 0 auto;
  place-items: center;
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  color: var(--mc-text-muted);
}

.mc-settings-content-card h2,
.mc-about-card h2 {
  margin: 0;
  font-size: 0.9375rem;
}

.mc-settings-content-card p,
.mc-about-card p {
  margin: 0.375rem 0 0;
  color: var(--mc-text-secondary);
  line-height: 1.5;
}

.mc-coming-soon {
  display: inline-block;
  margin-top: 0.75rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-about-mark {
  width: 2.75rem;
  height: 2.75rem;
}

.mc-about-list {
  margin: 1rem 0 0;
}

.mc-about-list > div {
  display: grid;
  grid-template-columns: 6rem minmax(0, 1fr);
  padding: 0.375rem 0;
}

.mc-about-list dt {
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-about-list dd {
  margin: 0;
  color: var(--mc-text-secondary);
  font-size: 0.75rem;
}

/* Responsive behavior */

.mc-sidebar-backdrop {
  display: none;
}

@media (max-width: 1200px) {
  .mc-projects-workspace {
    grid-template-columns: minmax(0, 1fr) 17rem;
  }

  .mc-project-table-head,
  .mc-project-row-v2 {
    grid-template-columns:
      minmax(11rem, 1.3fr)
      6.25rem
      7rem
      minmax(10rem, 1fr);
  }

  .mc-col-priority,
  .mc-col-version {
    display: none;
  }
}

@media (max-width: 1000px) {
  .mc-page {
    width: calc(100% - 2.5rem);
  }

  .mc-projects-workspace,
  .mc-project-detail-grid-v2 {
    grid-template-columns: 1fr;
  }

  .mc-project-preview,
  .mc-project-inspector-v2 {
    position: static;
  }

  .mc-project-preview {
    order: -1;
  }

  .mc-settings-layout {
    grid-template-columns: 11rem minmax(0, 1fr);
  }
}

@media (max-width: 820px) {
  .mc-page-header,
  .mc-project-detail-header {
    flex-direction: column;
  }

  .mc-project-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .mc-search {
    width: 100%;
  }

  .mc-detail-pair,
  .mc-form-split,
  .mc-theme-grid {
    grid-template-columns: 1fr;
  }

  .mc-form-section {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .mc-settings-layout {
    grid-template-columns: 1fr;
  }

  .mc-settings-nav {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 0.375rem;
  }

  .mc-settings-nav-item {
    flex: 0 0 auto;
  }

  .mc-scale-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .mc-shell,
  .mc-shell.is-sidebar-hidden {
    grid-template-columns: 1fr;
  }

  .mc-sidebar,
  .mc-shell.is-sidebar-hidden .mc-sidebar {
    position: fixed;
    z-index: 60;
    inset: 0 auto 0 0;
    width: min(17rem, calc(100vw - 3.5rem));
    pointer-events: none;
    opacity: 1;
    transform: translateX(-100%);
    box-shadow: var(--mc-shadow);
  }

  .mc-shell.is-mobile-sidebar-open .mc-sidebar {
    pointer-events: auto;
    transform: translateX(0);
  }

  .mc-sidebar-backdrop {
    position: fixed;
    z-index: 50;
    inset: 0;
    display: block;
    border: 0;
    background: var(--mc-overlay);
  }

  .mc-shellbar-title {
    display: none;
  }

  .mc-page {
    width: calc(100% - 1.5rem);
    padding-top: 1.25rem;
  }

  .mc-project-table-head {
    display: none;
  }

  .mc-project-row-v2 {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 0.75rem;
    min-height: 4.25rem;
  }

  .mc-col-status {
    display: block;
  }

  .mc-col-step-status,
  .mc-col-priority,
  .mc-col-version,
  .mc-col-current-step {
    display: none;
  }

  .mc-project-preview {
    display: none;
  }

  .mc-section-topline {
    flex-direction: column;
  }

  .mc-dialog-backdrop {
    padding: 0.75rem;
  }

  .mc-dialog-wide {
    width: 100%;
    max-height: calc(100vh - 1.5rem);
  }

  .mc-dialog-scroll {
    max-height: calc(100vh - 6rem);
  }
}

@media (max-width: 520px) {
  .mc-page {
    width: calc(100% - 1rem);
  }

  .mc-segmented-control {
    width: 100%;
  }

  .mc-segmented-control button {
    flex: 1;
    justify-content: center;
  }

  .mc-form-section {
    padding: 1rem;
  }

  .mc-scale-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mc-confirm-dialog {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .mc-dialog-close {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
  }

  .mc-dialog-actions {
    grid-column: 1 / -1;
  }
}
/* v0.1.2 desktop shell + semantic refinement */

.mc-titlebar {
  position: fixed;
  z-index: 100;
  inset: 0 0 auto 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 2.25rem;
  border-bottom: 1px solid var(--mc-border-subtle);
  background: color-mix(in srgb, var(--mc-bg) 94%, #ffffff 6%);
  user-select: none;
}

.mc-titlebar-left {
  display: flex;
  align-items: stretch;
  height: 100%;
  justify-self: start;
}

.mc-titlebar-center {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--mc-text-muted);
  font-size: 0.72rem;
  pointer-events: none;
}

.mc-titlebar-icon,
.mc-menu-button,
.mc-window-controls button {
  border: 0;
  background: transparent;
  color: var(--mc-text-secondary);
}

.mc-titlebar-icon {
  display: grid;
  place-items: center;
  width: 2.35rem;
  height: 100%;
  cursor: pointer;
}

.mc-titlebar-icon:hover,
.mc-menu-button:hover,
.mc-menu-button.is-active {
  background: var(--mc-surface-hover);
  color: var(--mc-text-primary);
}

.mc-menu-root {
  position: relative;
  height: 100%;
}

.mc-menu-button {
  height: 100%;
  padding: 0 0.7rem;
  font-size: 0.76rem;
  cursor: pointer;
}

.mc-menu-popover {
  position: absolute;
  top: calc(100% + 0.2rem);
  left: 0.2rem;
  width: 16rem;
  padding: 0.3rem;
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface-elevated);
  box-shadow: var(--mc-shadow);
}

.mc-menu-popover > button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  min-height: 2rem;
  padding: 0.3rem 0.55rem;
  border: 0;
  border-radius: var(--mc-radius-sm);
  background: transparent;
  color: var(--mc-text-secondary);
  text-align: left;
  cursor: pointer;
}

.mc-menu-popover > button:hover:not(:disabled) {
  background: var(--mc-surface-hover);
  color: var(--mc-text-primary);
}

.mc-menu-popover > button:disabled {
  cursor: default;
  opacity: 0.5;
}

.mc-menu-popover small {
  color: var(--mc-text-muted);
  font-size: 0.68rem;
}

.mc-menu-popover kbd {
  color: var(--mc-text-muted);
  font-size: 0.67rem;
}

.mc-menu-separator {
  height: 1px;
  margin: 0.25rem 0.35rem;
  background: var(--mc-border-subtle);
}

.mc-window-controls {
  display: flex;
  align-self: stretch;
  justify-self: end;
}

.mc-window-controls button {
  display: grid;
  place-items: center;
  width: 2.85rem;
  cursor: pointer;
}

.mc-window-controls button:hover {
  background: var(--mc-surface-hover);
  color: var(--mc-text-primary);
}

.mc-window-controls button.is-close:hover {
  background: #c42b1c;
  color: #ffffff;
}

.mc-shell {
  padding-top: 2.25rem;
}

.mc-sidebar {
  height: calc(100vh - 2.25rem);
}

.mc-main {
  height: calc(100vh - 2.25rem);
}

/* stronger semantic status / priority styling */

.mc-option-choice[data-tone="success"].is-selected,
.mc-state-badge[data-tone="success"] {
  border-color: color-mix(in srgb, var(--mc-success) 52%, transparent);
  background: var(--mc-success-soft);
  color: var(--mc-success);
}

.mc-option-choice[data-tone="info"].is-selected,
.mc-state-badge[data-tone="info"] {
  border-color: color-mix(in srgb, var(--mc-info) 52%, transparent);
  background: var(--mc-info-soft);
  color: var(--mc-info);
}

.mc-option-choice[data-tone="warning"].is-selected,
.mc-state-badge[data-tone="warning"] {
  border-color: color-mix(in srgb, var(--mc-warning) 55%, transparent);
  background: var(--mc-warning-soft);
  color: var(--mc-warning);
}

.mc-option-choice[data-tone="danger"].is-selected,
.mc-state-badge[data-tone="danger"] {
  border-color: color-mix(in srgb, var(--mc-danger) 58%, transparent);
  background: var(--mc-danger-soft);
  color: var(--mc-danger);
}

.mc-option-choice[data-tone="accent"].is-selected,
.mc-state-badge[data-tone="accent"] {
  border-color: var(--mc-accent-border);
  background: var(--mc-accent-soft);
  color: var(--mc-accent);
}

.mc-option-choice[data-tone="low"].is-selected,
.mc-state-badge[data-tone="low"] {
  border-color: color-mix(in srgb, var(--mc-priority-low) 55%, transparent);
  background: color-mix(in srgb, var(--mc-priority-low) 13%, transparent);
  color: var(--mc-priority-low);
}

.mc-option-choice[data-tone="medium"].is-selected,
.mc-state-badge[data-tone="medium"] {
  border-color: color-mix(in srgb, var(--mc-priority-medium) 58%, transparent);
  background: color-mix(in srgb, var(--mc-priority-medium) 13%, transparent);
  color: var(--mc-priority-medium);
}

.mc-option-choice[data-tone="high"].is-selected,
.mc-state-badge[data-tone="high"] {
  border-color: color-mix(in srgb, var(--mc-priority-high) 60%, transparent);
  background: color-mix(in srgb, var(--mc-priority-high) 13%, transparent);
  color: var(--mc-priority-high);
}

.mc-option-choice[data-tone="critical"].is-selected,
.mc-state-badge[data-tone="critical"] {
  border-color: var(--mc-priority-critical);
  background: color-mix(in srgb, var(--mc-priority-critical) 16%, transparent);
  color: var(--mc-priority-critical);
}

.mc-option-choice.is-selected .mc-option-dot,
.mc-state-badge .mc-state-dot {
  background: currentColor;
  box-shadow: 0 0 0 2px color-mix(in srgb, currentColor 20%, transparent);
}

/* keyboard shortcut settings */

.mc-settings-heading-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.mc-shortcut-list {
  overflow: hidden;
}

.mc-shortcut-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  min-height: 4rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--mc-border-subtle);
}

.mc-shortcut-row:last-child {
  border-bottom: 0;
}

.mc-shortcut-copy {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.mc-shortcut-copy strong {
  font-size: 0.8rem;
  font-weight: 600;
}

.mc-shortcut-copy span {
  color: var(--mc-text-muted);
  font-size: 0.72rem;
}

.mc-shortcut-actions {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.mc-shortcut-key {
  min-width: 7rem;
  min-height: 2rem;
  padding: 0 0.65rem;
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  color: var(--mc-text-secondary);
  font-family: inherit;
  font-size: 0.72rem;
  cursor: pointer;
}

.mc-shortcut-key:hover {
  border-color: var(--mc-border-strong);
  color: var(--mc-text-primary);
}

.mc-shortcut-key.is-recording {
  border-color: var(--mc-accent);
  background: var(--mc-accent-soft);
  color: var(--mc-accent);
}

.mc-settings-hint {
  margin-top: 0.75rem;
  color: var(--mc-text-muted);
  font-size: 0.72rem;
}

@media (max-width: 760px) {
  .mc-titlebar {
    grid-template-columns: 1fr auto;
  }

  .mc-titlebar-center {
    display: none;
  }

  .mc-menu-button {
    padding-inline: 0.45rem;
  }

  .mc-window-controls {
    display: none;
  }

  .mc-shortcut-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .mc-shortcut-actions {
    width: 100%;
  }

  .mc-shortcut-key {
    flex: 1;
  }
}

edits.new:
* {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  min-width: 100%;
  min-height: 100%;
  margin: 0;
}

html,
body {
  height: 100%;
}

body {
  overflow: hidden;
  background: var(--mc-bg);
  color: var(--mc-text-primary);
  font-family:
    Inter,
    ui-sans-serif,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  font-size: 0.875rem;
  text-rendering: optimizeLegibility;
}

button,
input,
textarea {
  font: inherit;
}

button {
  color: inherit;
}

a {
  color: inherit;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 0.125rem solid var(--mc-accent);
  outline-offset: 0.125rem;
}

kbd {
  padding: 0.15rem 0.35rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-xs);
  background: var(--mc-surface-raised);
  color: var(--mc-text-muted);
  font-family: inherit;
  font-size: 0.6875rem;
}

.mc-shell {
  display: grid;
  grid-template-columns: var(--mc-sidebar-width) minmax(0, 1fr);
  width: 100vw;
  height: 100vh;
  background: var(--mc-bg);
  transition: grid-template-columns 150ms ease;
}

.mc-shell.is-sidebar-hidden {
  grid-template-columns: 0 minmax(0, 1fr);
}

.mc-sidebar {
  position: relative;
  z-index: 30;
  display: flex;
  min-width: 0;
  flex-direction: column;
  overflow: hidden;
  padding: 0.75rem 0.625rem;
  border-right: 0.0625rem solid var(--mc-border-subtle);
  background: var(--mc-sidebar);
  transition:
    transform 150ms ease,
    opacity 120ms ease;
}

.mc-shell.is-sidebar-hidden .mc-sidebar {
  pointer-events: none;
  opacity: 0;
  transform: translateX(-100%);
}

.mc-brand {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  min-height: 2.5rem;
  padding: 0 0.5rem;
  margin-bottom: 0.875rem;
}

.mc-brand-mark {
  display: grid;
  width: 1.8125rem;
  height: 1.8125rem;
  flex: 0 0 auto;
  place-items: center;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface-raised);
  color: var(--mc-accent);
}

.mc-brand-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
}

.mc-brand-title {
  overflow: hidden;
  font-size: 0.8125rem;
  font-weight: 680;
  letter-spacing: -0.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mc-brand-version {
  margin-top: 0.125rem;
  color: var(--mc-text-muted);
  font-size: 0.625rem;
}

.mc-sidebar-close {
  margin-left: auto;
}

.mc-nav {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 0.1875rem;
}

.mc-nav-item {
  display: flex;
  height: 2.25rem;
  align-items: center;
  gap: 0.625rem;
  padding: 0 0.625rem;
  border-radius: var(--mc-radius-sm);
  color: var(--mc-text-secondary);
  text-decoration: none;
  transition:
    background 120ms ease,
    color 120ms ease;
}

.mc-nav-item:hover {
  background: var(--mc-surface-hover);
  color: var(--mc-text-primary);
}

.mc-nav-item.is-active {
  background: var(--mc-accent-soft);
  color: var(--mc-text-primary);
}

.mc-nav-item.is-active svg {
  color: var(--mc-accent);
}

.mc-sidebar-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.75rem 0.625rem 0.25rem;
  border-top: 0.0625rem solid var(--mc-border-subtle);
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-main-frame {
  display: flex;
  min-width: 0;
  height: 100vh;
  flex-direction: column;
}

.mc-shellbar {
  display: flex;
  min-height: var(--mc-shellbar-height);
  flex: 0 0 var(--mc-shellbar-height);
  align-items: center;
  gap: 0.625rem;
  padding: 0 0.875rem;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
  background: color-mix(in srgb, var(--mc-bg) 86%, transparent);
}

.mc-shellbar-title {
  color: var(--mc-text-muted);
  font-size: 0.75rem;
  font-weight: 600;
}

.mc-main {
  min-width: 0;
  flex: 1;
  overflow: auto;
}

.mc-page {
  width: min(var(--mc-page-max), calc(100% - 4rem));
  margin: 0 auto;
  padding: 2rem 0 5rem;
}

.mc-page-form {
  max-width: 72rem;
}

.mc-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
  margin-bottom: 1.75rem;
}

.mc-eyebrow {
  margin: 0 0 0.4375rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mc-page-header h1,
.mc-project-detail-header h1 {
  margin: 0;
  font-size: clamp(1.375rem, 2.1vw, 1.75rem);
  font-weight: 680;
  letter-spacing: -0.035em;
}

.mc-page-description {
  max-width: 38rem;
  margin: 0.5rem 0 0;
  color: var(--mc-text-secondary);
  line-height: 1.55;
}

.mc-button {
  display: inline-flex;
  min-height: 2.125rem;
  align-items: center;
  justify-content: center;
  gap: 0.4375rem;
  padding: 0 0.75rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  color: var(--mc-text-primary);
  text-decoration: none;
  cursor: pointer;
  transition:
    border-color 120ms ease,
    background 120ms ease;
}

.mc-button:hover:not(:disabled) {
  border-color: var(--mc-border-strong);
  background: var(--mc-surface-hover);
}

.mc-button:disabled,
.mc-icon-button:disabled {
  opacity: 0.55;
  cursor: default;
}

.mc-button-primary {
  border-color: transparent;
  background: var(--mc-accent);
  color: #fff;
}

.mc-button-primary:hover:not(:disabled) {
  border-color: transparent;
  background: var(--mc-accent-hover);
}

.mc-button-danger-solid {
  border-color: transparent;
  background: var(--mc-danger);
  color: #fff;
}

.mc-button-block {
  width: 100%;
}

.mc-icon-button {
  display: grid;
  width: 2rem;
  height: 2rem;
  flex: 0 0 auto;
  place-items: center;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  cursor: pointer;
}

.mc-icon-button:hover:not(:disabled) {
  background: var(--mc-surface-hover);
}

.mc-panel {
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface);
}

.mc-muted {
  color: var(--mc-text-muted);
}

.mc-back-link {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  margin-bottom: 1.25rem;
  color: var(--mc-text-secondary);
  text-decoration: none;
}

.mc-back-link:hover {
  color: var(--mc-text-primary);
}

.mc-header-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.mc-state-badge {
  --badge-color: var(--mc-text-secondary);
  --badge-bg: var(--mc-neutral-soft);
  display: inline-flex;
  min-height: 1.5rem;
  align-items: center;
  gap: 0.375rem;
  padding: 0.1875rem 0.4375rem;
  border: 0.0625rem solid color-mix(in srgb, var(--badge-color) 26%, transparent);
  border-radius: 999px;
  background: var(--badge-bg);
  color: var(--badge-color);
  font-size: 0.6875rem;
  font-weight: 620;
  line-height: 1;
  white-space: nowrap;
}

.mc-state-dot {
  width: 0.375rem;
  height: 0.375rem;
  border-radius: 50%;
  background: currentColor;
}

[data-tone="accent"] {
  --badge-color: var(--mc-accent);
  --badge-bg: var(--mc-accent-soft);
}

[data-tone="success"] {
  --badge-color: var(--mc-success);
  --badge-bg: var(--mc-success-soft);
}

[data-tone="warning"],
[data-tone="medium"] {
  --badge-color: var(--mc-priority-medium);
  --badge-bg: var(--mc-warning-soft);
}

[data-tone="danger"],
[data-tone="high"] {
  --badge-color: var(--mc-priority-high);
  --badge-bg: var(--mc-danger-soft);
}

[data-tone="critical"] {
  --badge-color: var(--mc-priority-critical);
  --badge-bg: var(--mc-danger-soft);
}

[data-tone="info"] {
  --badge-color: var(--mc-info);
  --badge-bg: var(--mc-info-soft);
}

[data-tone="low"] {
  --badge-color: var(--mc-priority-low);
  --badge-bg: var(--mc-neutral-soft);
}

/* Projects */

.mc-project-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.875rem;
}

.mc-segmented-control {
  display: inline-flex;
  padding: 0.1875rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface);
}

.mc-segmented-control button {
  display: inline-flex;
  min-height: 1.875rem;
  align-items: center;
  gap: 0.375rem;
  padding: 0 0.625rem;
  border: 0;
  border-radius: 0.25rem;
  background: transparent;
  color: var(--mc-text-muted);
  cursor: pointer;
}

.mc-segmented-control button.is-active {
  background: var(--mc-surface-elevated);
  color: var(--mc-text-primary);
  box-shadow: 0 0 0 0.0625rem var(--mc-border);
}

.mc-search {
  display: flex;
  width: min(22rem, 42vw);
  height: 2.125rem;
  align-items: center;
  gap: 0.5rem;
  padding: 0 0.625rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface);
  color: var(--mc-text-muted);
}

.mc-search:focus-within {
  border-color: var(--mc-accent-border);
}

.mc-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--mc-text-primary);
}

.mc-projects-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 20rem;
  gap: 0.875rem;
  align-items: start;
}

.mc-project-table-v2 {
  min-width: 0;
  overflow: hidden;
}

.mc-project-table-head,
.mc-project-row-v2 {
  display: grid;
  grid-template-columns:
    minmax(11rem, 1.35fr)
    6.25rem
    7.25rem
    6.5rem
    5rem
    minmax(11rem, 1fr);
  gap: 0.75rem;
  align-items: center;
}

.mc-project-table-head {
  min-height: 2.375rem;
  padding: 0 0.875rem;
  border-bottom: 0.0625rem solid var(--mc-border);
  background: var(--mc-surface-raised);
  color: var(--mc-text-muted);
  font-size: 0.625rem;
  font-weight: 650;
  letter-spacing: 0.045em;
  text-transform: uppercase;
}

.mc-project-row-v2 {
  width: 100%;
  min-height: 4rem;
  padding: 0.625rem 0.875rem;
  border: 0;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
  background: transparent;
  color: var(--mc-text-secondary);
  text-align: left;
  cursor: pointer;
}

.mc-project-row-v2:last-child {
  border-bottom: 0;
}

.mc-project-row-v2:hover,
.mc-project-row-v2.is-selected {
  background: var(--mc-surface-hover);
}

.mc-project-row-v2.is-selected {
  box-shadow: inset 0.125rem 0 0 var(--mc-accent);
}

.mc-project-identity {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.mc-project-identity strong {
  overflow: hidden;
  color: var(--mc-text-primary);
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mc-project-identity small {
  overflow: hidden;
  margin-top: 0.25rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mc-current-step-cell {
  overflow: hidden;
  color: var(--mc-text-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mc-project-version {
  color: var(--mc-text-muted);
  font-size: 0.75rem;
}

.mc-project-preview {
  position: sticky;
  top: 1rem;
  padding: 1rem;
}

.mc-project-preview-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.mc-project-preview-heading h2 {
  margin: 0;
  font-size: 1rem;
}

.mc-project-preview-description {
  margin: 0.875rem 0 1rem;
  color: var(--mc-text-secondary);
  font-size: 0.8125rem;
  line-height: 1.55;
}

.mc-preview-current-step {
  padding: 0.875rem;
  margin-bottom: 1rem;
  border: 0.0625rem solid var(--mc-border-subtle);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
}

.mc-preview-current-step > span {
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-preview-current-step strong {
  display: block;
  margin: 0.375rem 0 0.625rem;
  font-size: 0.875rem;
  line-height: 1.4;
}

.mc-badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
}

.mc-inspector-list {
  margin: 0 0 1rem;
}

.mc-inspector-list > div {
  display: flex;
  min-height: 2.25rem;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
}

.mc-inspector-list > div:last-child {
  border-bottom: 0;
}

.mc-inspector-list dt {
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-inspector-list dd {
  margin: 0;
  color: var(--mc-text-secondary);
  font-size: 0.75rem;
  text-align: right;
}

.mc-project-empty {
  display: flex;
  min-height: 22rem;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 3rem;
  text-align: center;
}

.mc-empty-icon {
  display: grid;
  width: 3.5rem;
  height: 3.5rem;
  place-items: center;
  margin-bottom: 1rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-lg);
  background: var(--mc-surface-raised);
  color: var(--mc-text-muted);
}

.mc-project-empty h2 {
  margin: 0;
  font-size: 0.9375rem;
}

.mc-project-empty p {
  max-width: 28rem;
  margin: 0.5rem 0 0;
  color: var(--mc-text-secondary);
  line-height: 1.55;
}

.mc-empty-action {
  margin-top: 1rem;
}

/* Project detail */

.mc-project-detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
  margin-bottom: 1.25rem;
}

.mc-title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.mc-project-title-block > p {
  max-width: 44rem;
  margin: 0.5rem 0 0;
  color: var(--mc-text-secondary);
  line-height: 1.5;
}

.mc-project-meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4375rem;
  margin-top: 0.75rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-meta-separator {
  color: var(--mc-text-faint);
}

.mc-more-button {
  color: var(--mc-danger);
}

.mc-detail-tabs {
  display: flex;
  gap: 0.125rem;
  overflow-x: auto;
  margin: 0 -0.25rem 1rem;
  padding: 0 0.25rem 0.625rem;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
}

.mc-detail-tabs button {
  flex: 0 0 auto;
  padding: 0.4375rem 0.625rem;
  border: 0;
  border-radius: var(--mc-radius-sm);
  background: transparent;
  color: var(--mc-text-muted);
  font-size: 0.75rem;
  cursor: pointer;
}

.mc-detail-tabs button.is-active {
  background: var(--mc-surface-raised);
  color: var(--mc-text-primary);
}

.mc-detail-tabs button:disabled {
  opacity: 0.42;
  cursor: default;
}

.mc-project-detail-grid-v2 {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 19rem;
  gap: 0.875rem;
  align-items: start;
}

.mc-project-detail-main-v2 {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.875rem;
}

.mc-current-step-card {
  padding: 1.25rem;
  border-color: var(--mc-accent-border);
  background:
    linear-gradient(180deg, var(--mc-accent-soft), transparent 70%),
    var(--mc-surface);
}

.mc-section-topline {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.mc-current-step-card h2 {
  max-width: 48rem;
  margin: 0;
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  line-height: 1.3;
}

.mc-step-context {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4375rem;
  margin-top: 1rem;
  color: var(--mc-text-muted);
  font-size: 0.75rem;
}

.mc-detail-pair {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.875rem;
}

.mc-detail-section-v2 {
  min-height: 14rem;
  padding: 1rem;
}

.mc-section-heading-inline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.75rem;
}

.mc-section-heading-inline h2 {
  margin: 0;
  font-size: 0.875rem;
}

.mc-section-heading-inline > span {
  display: grid;
  min-width: 1.5rem;
  height: 1.5rem;
  place-items: center;
  border-radius: 999px;
  background: var(--mc-surface-raised);
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-work-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 0;
  margin: 0;
  list-style: none;
}

.mc-work-list li {
  display: flex;
  min-height: 2.5rem;
  align-items: flex-start;
  gap: 0.625rem;
  padding: 0.625rem 0;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
  color: var(--mc-text-secondary);
  line-height: 1.45;
}

.mc-work-list li:last-child {
  border-bottom: 0;
}

.mc-work-index {
  display: grid;
  width: 1.25rem;
  height: 1.25rem;
  flex: 0 0 auto;
  place-items: center;
  border: 0.0625rem solid var(--mc-border);
  border-radius: 50%;
  color: var(--mc-text-muted);
  font-size: 0.625rem;
}

.mc-blocker-dot {
  width: 0.4375rem;
  height: 0.4375rem;
  flex: 0 0 auto;
  margin-top: 0.4rem;
  border-radius: 50%;
  background: var(--mc-danger);
}

.mc-clear-state {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--mc-success);
  font-size: 0.8125rem;
}

.mc-last-completed-card {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem;
}

.mc-last-completed-icon {
  display: grid;
  width: 2rem;
  height: 2rem;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 50%;
  background: var(--mc-success-soft);
  color: var(--mc-success);
}

.mc-last-completed-card strong {
  font-size: 0.8125rem;
}

.mc-project-inspector-v2 {
  position: sticky;
  top: 1rem;
  padding: 1rem;
}

.mc-inspector-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.625rem;
}

.mc-inspector-heading h2 {
  margin: 0;
  font-size: 0.9375rem;
}

.mc-inspector-heading svg {
  color: var(--mc-text-muted);
}

.mc-inspector-divider {
  height: 0.0625rem;
  margin: 0.875rem 0;
  background: var(--mc-border-subtle);
}

.mc-location-block + .mc-location-block {
  margin-top: 1rem;
}

.mc-location-label {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  margin-bottom: 0.375rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-location-block code,
.mc-location-block a {
  display: block;
  overflow: hidden;
  color: var(--mc-text-secondary);
  font-family: inherit;
  font-size: 0.6875rem;
  line-height: 1.45;
  text-overflow: ellipsis;
  text-decoration: none;
  word-break: break-all;
}

.mc-location-block a:hover {
  color: var(--mc-accent);
}

/* Forms */

.mc-project-form-v2 {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
}

.mc-form-section {
  display: grid;
  grid-template-columns: 14rem minmax(0, 1fr);
  gap: 2rem;
  padding: 1.25rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface);
}

.mc-form-section-copy h2 {
  margin: 0;
  font-size: 0.9375rem;
}

.mc-form-section-copy > p:last-child {
  margin: 0.5rem 0 0;
  color: var(--mc-text-muted);
  font-size: 0.75rem;
  line-height: 1.5;
}

.mc-form-section-fields {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1rem;
}

.mc-form-split {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.875rem;
}

.mc-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.375rem;
}

.mc-field > span,
.mc-option-picker legend {
  color: var(--mc-text-secondary);
  font-size: 0.6875rem;
  font-weight: 600;
}

.mc-field input,
.mc-field textarea {
  width: 100%;
  padding: 0.625rem 0.6875rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  outline: 0;
  background: var(--mc-surface-raised);
  color: var(--mc-text-primary);
}

.mc-field input {
  min-height: 2.375rem;
}

.mc-field textarea {
  resize: vertical;
  line-height: 1.5;
}

.mc-field input:focus,
.mc-field textarea:focus {
  border-color: var(--mc-accent-border);
  box-shadow: 0 0 0 0.125rem var(--mc-accent-soft);
}

.mc-field input::placeholder,
.mc-field textarea::placeholder {
  color: var(--mc-text-faint);
}

.mc-option-picker {
  min-width: 0;
  padding: 0;
  margin: 0;
  border: 0;
}

.mc-option-picker legend {
  padding: 0;
  margin-bottom: 0.4375rem;
}

.mc-option-picker-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
}

.mc-option-choice {
  --badge-color: var(--mc-text-secondary);
  --badge-bg: var(--mc-neutral-soft);
  display: inline-flex;
  min-height: 2rem;
  align-items: center;
  gap: 0.375rem;
  padding: 0 0.625rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  color: var(--mc-text-secondary);
  cursor: pointer;
}

.mc-option-choice:hover {
  border-color: var(--mc-border-strong);
}

.mc-option-choice.is-selected {
  border-color: color-mix(in srgb, var(--badge-color) 42%, var(--mc-border));
  background: var(--badge-bg);
  color: var(--badge-color);
}

.mc-option-dot {
  width: 0.375rem;
  height: 0.375rem;
  border-radius: 50%;
  background: currentColor;
}

.mc-form-error {
  padding: 0.75rem 0.875rem;
  margin: 0;
  border: 0.0625rem solid color-mix(in srgb, var(--mc-danger) 35%, transparent);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-danger-soft);
  color: var(--mc-danger);
}

.mc-form-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding-top: 0.25rem;
}

/* Dialogs */

.mc-dialog-backdrop {
  position: fixed;
  z-index: 100;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background: var(--mc-overlay);
}

.mc-dialog {
  position: relative;
  width: min(30rem, 100%);
  max-height: calc(100vh - 3rem);
  overflow: hidden;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-lg);
  background: var(--mc-surface-elevated);
  box-shadow: var(--mc-shadow);
}

.mc-dialog-wide {
  width: min(68rem, 100%);
}

.mc-dialog-header {
  padding: 1rem 1.125rem;
  border-bottom: 0.0625rem solid var(--mc-border);
}

.mc-dialog-header h2,
.mc-confirm-copy h2 {
  margin: 0;
  font-size: 1rem;
}

.mc-dialog-scroll {
  max-height: calc(100vh - 9rem);
  overflow: auto;
  padding: 1rem;
}

.mc-confirm-dialog {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.875rem;
  padding: 1.125rem;
}

.mc-confirm-icon {
  display: grid;
  width: 2.25rem;
  height: 2.25rem;
  place-items: center;
  border-radius: 50%;
  background: var(--mc-warning-soft);
  color: var(--mc-warning);
}

.mc-confirm-icon.is-danger {
  background: var(--mc-danger-soft);
  color: var(--mc-danger);
}

.mc-confirm-copy p {
  margin: 0.4375rem 0 0;
  color: var(--mc-text-secondary);
  font-size: 0.8125rem;
  line-height: 1.5;
}

.mc-dialog-close {
  border: 0;
  background: transparent;
}

.mc-dialog-actions {
  display: flex;
  grid-column: 2 / -1;
  justify-content: flex-end;
  gap: 0.5rem;
  margin-top: 0.375rem;
}

/* Settings */

.mc-settings-layout {
  display: grid;
  grid-template-columns: 14rem minmax(0, 1fr);
  gap: 1.5rem;
  align-items: start;
}

.mc-settings-nav {
  display: flex;
  flex-direction: column;
  gap: 0.1875rem;
}

.mc-settings-nav-item {
  display: flex;
  min-height: 2.25rem;
  align-items: center;
  gap: 0.625rem;
  padding: 0 0.625rem;
  border-radius: var(--mc-radius-sm);
  color: var(--mc-text-secondary);
  text-decoration: none;
}

.mc-settings-nav-item:hover {
  background: var(--mc-surface-hover);
  color: var(--mc-text-primary);
}

.mc-settings-nav-item.is-active {
  background: var(--mc-accent-soft);
  color: var(--mc-text-primary);
}

.mc-settings-content {
  min-width: 0;
  max-width: 58rem;
}

.mc-settings-heading {
  margin-bottom: 1rem;
}

.mc-settings-heading h2 {
  margin: 0;
  font-size: 1rem;
}

.mc-settings-heading p {
  margin: 0.375rem 0 0;
  color: var(--mc-text-muted);
  font-size: 0.75rem;
}

.mc-settings-group {
  overflow: hidden;
}

.mc-setting-row,
.mc-scale-header {
  display: flex;
  min-height: 4rem;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  padding: 0.875rem 1rem;
  border-bottom: 0.0625rem solid var(--mc-border-subtle);
}

.mc-setting-row:last-child {
  border-bottom: 0;
}

.mc-setting-row > div,
.mc-scale-header > div {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.mc-setting-row strong,
.mc-scale-header strong {
  font-size: 0.8125rem;
}

.mc-setting-row span,
.mc-scale-header span {
  color: var(--mc-text-muted);
  font-size: 0.75rem;
  line-height: 1.45;
}

.mc-toggle {
  position: relative;
  width: 2.375rem;
  height: 1.375rem;
  flex: 0 0 auto;
  padding: 0;
  border: 0.0625rem solid var(--mc-border);
  border-radius: 999px;
  background: var(--mc-surface-raised);
  cursor: pointer;
}

.mc-toggle span {
  position: absolute;
  top: 0.1875rem;
  left: 0.1875rem;
  width: 0.875rem;
  height: 0.875rem;
  border-radius: 50%;
  background: var(--mc-text-muted);
  transition: transform 140ms ease;
}

.mc-toggle.is-on {
  border-color: var(--mc-accent);
  background: var(--mc-accent);
}

.mc-toggle.is-on span {
  background: #fff;
  transform: translateX(1rem);
}

.mc-theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.625rem;
}

.mc-theme-choice {
  display: flex;
  min-height: 6rem;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.875rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface);
  text-align: left;
  cursor: pointer;
}

.mc-theme-choice:hover {
  background: var(--mc-surface-hover);
}

.mc-theme-choice.is-selected {
  border-color: var(--mc-accent);
  box-shadow: inset 0 0 0 0.0625rem var(--mc-accent);
}

.mc-theme-choice svg {
  margin-top: 0.0625rem;
  color: var(--mc-text-secondary);
}

.mc-theme-choice.is-selected svg {
  color: var(--mc-accent);
}

.mc-theme-choice > span {
  display: flex;
  flex-direction: column;
}

.mc-theme-choice strong {
  font-size: 0.8125rem;
}

.mc-theme-choice small {
  margin-top: 0.3125rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
  line-height: 1.45;
}

.mc-scale-value {
  color: var(--mc-accent);
}

.mc-scale-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
  padding: 1rem;
}

.mc-scale-choice {
  min-height: 2.5rem;
  border: 0.0625rem solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  color: var(--mc-text-secondary);
  cursor: pointer;
}

.mc-scale-choice:hover {
  background: var(--mc-surface-hover);
}

.mc-scale-choice.is-selected {
  border-color: var(--mc-accent);
  background: var(--mc-accent-soft);
  color: var(--mc-accent);
  font-weight: 650;
}

.mc-setting-note {
  padding: 0.75rem 1rem;
  border-top: 0.0625rem solid var(--mc-border-subtle);
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
  line-height: 1.5;
}

.mc-settings-content-card,
.mc-about-card {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1rem;
}

.mc-settings-card-icon {
  display: grid;
  width: 2.25rem;
  height: 2.25rem;
  flex: 0 0 auto;
  place-items: center;
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  color: var(--mc-text-muted);
}

.mc-settings-content-card h2,
.mc-about-card h2 {
  margin: 0;
  font-size: 0.9375rem;
}

.mc-settings-content-card p,
.mc-about-card p {
  margin: 0.375rem 0 0;
  color: var(--mc-text-secondary);
  line-height: 1.5;
}

.mc-coming-soon {
  display: inline-block;
  margin-top: 0.75rem;
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-about-mark {
  width: 2.75rem;
  height: 2.75rem;
}

.mc-about-list {
  margin: 1rem 0 0;
}

.mc-about-list > div {
  display: grid;
  grid-template-columns: 6rem minmax(0, 1fr);
  padding: 0.375rem 0;
}

.mc-about-list dt {
  color: var(--mc-text-muted);
  font-size: 0.6875rem;
}

.mc-about-list dd {
  margin: 0;
  color: var(--mc-text-secondary);
  font-size: 0.75rem;
}

/* Responsive behavior */

.mc-sidebar-backdrop {
  display: none;
}

@media (max-width: 1200px) {
  .mc-projects-workspace {
    grid-template-columns: minmax(0, 1fr) 17rem;
  }

  .mc-project-table-head,
  .mc-project-row-v2 {
    grid-template-columns:
      minmax(11rem, 1.3fr)
      6.25rem
      7rem
      minmax(10rem, 1fr);
  }

  .mc-col-priority,
  .mc-col-version {
    display: none;
  }
}

@media (max-width: 1000px) {
  .mc-page {
    width: calc(100% - 2.5rem);
  }

  .mc-projects-workspace,
  .mc-project-detail-grid-v2 {
    grid-template-columns: 1fr;
  }

  .mc-project-preview,
  .mc-project-inspector-v2 {
    position: static;
  }

  .mc-project-preview {
    order: -1;
  }

  .mc-settings-layout {
    grid-template-columns: 11rem minmax(0, 1fr);
  }
}

@media (max-width: 820px) {
  .mc-page-header,
  .mc-project-detail-header {
    flex-direction: column;
  }

  .mc-project-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .mc-search {
    width: 100%;
  }

  .mc-detail-pair,
  .mc-form-split,
  .mc-theme-grid {
    grid-template-columns: 1fr;
  }

  .mc-form-section {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .mc-settings-layout {
    grid-template-columns: 1fr;
  }

  .mc-settings-nav {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 0.375rem;
  }

  .mc-settings-nav-item {
    flex: 0 0 auto;
  }

  .mc-scale-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .mc-shell,
  .mc-shell.is-sidebar-hidden {
    grid-template-columns: 1fr;
  }

  .mc-sidebar,
  .mc-shell.is-sidebar-hidden .mc-sidebar {
    position: fixed;
    z-index: 60;
    inset: 0 auto 0 0;
    width: min(17rem, calc(100vw - 3.5rem));
    pointer-events: none;
    opacity: 1;
    transform: translateX(-100%);
    box-shadow: var(--mc-shadow);
  }

  .mc-shell.is-mobile-sidebar-open .mc-sidebar {
    pointer-events: auto;
    transform: translateX(0);
  }

  .mc-sidebar-backdrop {
    position: fixed;
    z-index: 50;
    inset: 0;
    display: block;
    border: 0;
    background: var(--mc-overlay);
  }

  .mc-shellbar-title {
    display: none;
  }

  .mc-page {
    width: calc(100% - 1.5rem);
    padding-top: 1.25rem;
  }

  .mc-project-table-head {
    display: none;
  }

  .mc-project-row-v2 {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 0.75rem;
    min-height: 4.25rem;
  }

  .mc-col-status {
    display: block;
  }

  .mc-col-step-status,
  .mc-col-priority,
  .mc-col-version,
  .mc-col-current-step {
    display: none;
  }

  .mc-project-preview {
    display: none;
  }

  .mc-section-topline {
    flex-direction: column;
  }

  .mc-dialog-backdrop {
    padding: 0.75rem;
  }

  .mc-dialog-wide {
    width: 100%;
    max-height: calc(100vh - 1.5rem);
  }

  .mc-dialog-scroll {
    max-height: calc(100vh - 6rem);
  }
}

@media (max-width: 520px) {
  .mc-page {
    width: calc(100% - 1rem);
  }

  .mc-segmented-control {
    width: 100%;
  }

  .mc-segmented-control button {
    flex: 1;
    justify-content: center;
  }

  .mc-form-section {
    padding: 1rem;
  }

  .mc-scale-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mc-confirm-dialog {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .mc-dialog-close {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
  }

  .mc-dialog-actions {
    grid-column: 1 / -1;
  }
}
/* v0.1.2 desktop shell + semantic refinement */

.mc-titlebar {
  position: fixed;
  z-index: 100;
  inset: 0 0 auto 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 2.25rem;
  border-bottom: 1px solid var(--mc-border-subtle);
  background: color-mix(in srgb, var(--mc-bg) 94%, #ffffff 6%);
  user-select: none;
}

.mc-titlebar-left {
  display: flex;
  align-items: stretch;
  height: 100%;
  justify-self: start;
}

.mc-titlebar-center {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--mc-text-muted);
  font-size: 0.72rem;
  pointer-events: none;
}

.mc-titlebar-icon,
.mc-menu-button,
.mc-window-controls button {
  border: 0;
  background: transparent;
  color: var(--mc-text-secondary);
}

.mc-titlebar-icon {
  display: grid;
  place-items: center;
  width: 2.35rem;
  height: 100%;
  cursor: pointer;
}

.mc-titlebar-icon:hover,
.mc-menu-button:hover,
.mc-menu-button.is-active {
  background: var(--mc-surface-hover);
  color: var(--mc-text-primary);
}

.mc-menu-root {
  position: relative;
  height: 100%;
}

.mc-menu-button {
  height: 100%;
  padding: 0 0.7rem;
  font-size: 0.76rem;
  cursor: pointer;
}

.mc-menu-popover {
  position: absolute;
  top: calc(100% + 0.2rem);
  left: 0.2rem;
  width: 16rem;
  padding: 0.3rem;
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface-elevated);
  box-shadow: var(--mc-shadow);
}

.mc-menu-popover > button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  min-height: 2rem;
  padding: 0.3rem 0.55rem;
  border: 0;
  border-radius: var(--mc-radius-sm);
  background: transparent;
  color: var(--mc-text-secondary);
  text-align: left;
  cursor: pointer;
}

.mc-menu-popover > button:hover:not(:disabled) {
  background: var(--mc-surface-hover);
  color: var(--mc-text-primary);
}

.mc-menu-popover > button:disabled {
  cursor: default;
  opacity: 0.5;
}

.mc-menu-popover small {
  color: var(--mc-text-muted);
  font-size: 0.68rem;
}

.mc-menu-popover kbd {
  color: var(--mc-text-muted);
  font-size: 0.67rem;
}

.mc-menu-separator {
  height: 1px;
  margin: 0.25rem 0.35rem;
  background: var(--mc-border-subtle);
}

.mc-window-controls {
  display: flex;
  align-self: stretch;
  justify-self: end;
}

.mc-window-controls button {
  display: grid;
  place-items: center;
  width: 2.85rem;
  cursor: pointer;
}

.mc-window-controls button:hover {
  background: var(--mc-surface-hover);
  color: var(--mc-text-primary);
}

.mc-window-controls button.is-close:hover {
  background: #c42b1c;
  color: #ffffff;
}

.mc-shell {
  padding-top: 2.25rem;
}

.mc-sidebar {
  height: calc(100vh - 2.25rem);
}

.mc-main {
  height: calc(100vh - 2.25rem);
}

/* stronger semantic status / priority styling */

.mc-option-choice[data-tone="success"].is-selected,
.mc-state-badge[data-tone="success"] {
  border-color: color-mix(in srgb, var(--mc-success) 52%, transparent);
  background: var(--mc-success-soft);
  color: var(--mc-success);
}

.mc-option-choice[data-tone="info"].is-selected,
.mc-state-badge[data-tone="info"] {
  border-color: color-mix(in srgb, var(--mc-info) 52%, transparent);
  background: var(--mc-info-soft);
  color: var(--mc-info);
}

.mc-option-choice[data-tone="warning"].is-selected,
.mc-state-badge[data-tone="warning"] {
  border-color: color-mix(in srgb, var(--mc-warning) 55%, transparent);
  background: var(--mc-warning-soft);
  color: var(--mc-warning);
}

.mc-option-choice[data-tone="danger"].is-selected,
.mc-state-badge[data-tone="danger"] {
  border-color: color-mix(in srgb, var(--mc-danger) 58%, transparent);
  background: var(--mc-danger-soft);
  color: var(--mc-danger);
}

.mc-option-choice[data-tone="accent"].is-selected,
.mc-state-badge[data-tone="accent"] {
  border-color: var(--mc-accent-border);
  background: var(--mc-accent-soft);
  color: var(--mc-accent);
}

.mc-option-choice[data-tone="low"].is-selected,
.mc-state-badge[data-tone="low"] {
  border-color: color-mix(in srgb, var(--mc-priority-low) 55%, transparent);
  background: color-mix(in srgb, var(--mc-priority-low) 13%, transparent);
  color: var(--mc-priority-low);
}

.mc-option-choice[data-tone="medium"].is-selected,
.mc-state-badge[data-tone="medium"] {
  border-color: color-mix(in srgb, var(--mc-priority-medium) 58%, transparent);
  background: color-mix(in srgb, var(--mc-priority-medium) 13%, transparent);
  color: var(--mc-priority-medium);
}

.mc-option-choice[data-tone="high"].is-selected,
.mc-state-badge[data-tone="high"] {
  border-color: color-mix(in srgb, var(--mc-priority-high) 60%, transparent);
  background: color-mix(in srgb, var(--mc-priority-high) 13%, transparent);
  color: var(--mc-priority-high);
}

.mc-option-choice[data-tone="critical"].is-selected,
.mc-state-badge[data-tone="critical"] {
  border-color: var(--mc-priority-critical);
  background: color-mix(in srgb, var(--mc-priority-critical) 16%, transparent);
  color: var(--mc-priority-critical);
}

.mc-option-choice.is-selected .mc-option-dot,
.mc-state-badge .mc-state-dot {
  background: currentColor;
  box-shadow: 0 0 0 2px color-mix(in srgb, currentColor 20%, transparent);
}

/* keyboard shortcut settings */

.mc-settings-heading-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.mc-shortcut-list {
  overflow: hidden;
}

.mc-shortcut-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  min-height: 4rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--mc-border-subtle);
}

.mc-shortcut-row:last-child {
  border-bottom: 0;
}

.mc-shortcut-copy {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.mc-shortcut-copy strong {
  font-size: 0.8rem;
  font-weight: 600;
}

.mc-shortcut-copy span {
  color: var(--mc-text-muted);
  font-size: 0.72rem;
}

.mc-shortcut-actions {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.mc-shortcut-key {
  min-width: 7rem;
  min-height: 2rem;
  padding: 0 0.65rem;
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  color: var(--mc-text-secondary);
  font-family: inherit;
  font-size: 0.72rem;
  cursor: pointer;
}

.mc-shortcut-key:hover {
  border-color: var(--mc-border-strong);
  color: var(--mc-text-primary);
}

.mc-shortcut-key.is-recording {
  border-color: var(--mc-accent);
  background: var(--mc-accent-soft);
  color: var(--mc-accent);
}

.mc-settings-hint {
  margin-top: 0.75rem;
  color: var(--mc-text-muted);
  font-size: 0.72rem;
}

@media (max-width: 760px) {
  .mc-titlebar {
    grid-template-columns: 1fr auto;
  }

  .mc-titlebar-center {
    display: none;
  }

  .mc-menu-button {
    padding-inline: 0.45rem;
  }

  .mc-window-controls {
    display: none;
  }

  .mc-shortcut-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .mc-shortcut-actions {
    width: 100%;
  }

  .mc-shortcut-key {
    flex: 1;
  }
}
/* v0.1.2.1 polish fixes */

/* Settings navigation: remove native/default gray button appearance. */

.mc-settings-nav {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.2rem;
}

.mc-settings-nav button {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  width: 100%;
  min-height: 2.25rem;
  padding: 0.45rem 0.65rem;
  border: 1px solid transparent;
  border-radius: var(--mc-radius-sm);
  background: transparent;
  color: var(--mc-text-secondary);
  text-align: left;
  font: inherit;
  font-size: 0.78rem;
